44	#include "error_code.h"
45	
46	namespace aria2 {
47	
48	class DiskAdaptor;
49	class WrDiskCache;
50	
51	class WrDiskCacheEntry {
52	public:
53	  struct DataCell {
54	    // Where the data is going to be put in DiskAdaptor
55	    int64_t goff;
56	    // data must be len+offset bytes. Thus, the cached data is
57	    // [data+offset, data+offset+len).
58	    unsigned char* data;
59	    size_t offset;
60	    size_t len;
61	    // valid memory range from data+offset
62	    size_t capacity;
63	    bool operator<(const DataCell& rhs) const { return goff < rhs.goff; }
64	  };
65	
66	  typedef std::set<DataCell*, DerefLess<DataCell*>> DataCellSet;
67	
68	  WrDiskCacheEntry(const std::shared_ptr<DiskAdaptor>& diskAdaptor);
69	  ~WrDiskCacheEntry();
70	
71	  // Flushes the cached data to the disk and deletes them.
72	  void writeToDisk();
73	  // Deletes cached data without flushing to the disk.
74	  void clear();
75	
76	  // Caches |dataCell|
77	  bool cacheData(DataCell* dataCell);
78	
79	  // Appends into last dataCell in set_ if the region is
80	  // contagious. Returns the number of copied bytes.
81	  size_t append(int64_t goff, const unsigned char* data, size_t len);
82	
83	  size_t getSize() const { return size_; }
84	  void setSizeKey(size_t sizeKey) { sizeKey_ = sizeKey; }
85	  size_t getSizeKey() const { return sizeKey_; }
86	  void setLastUpdate(int64_t clock) { lastUpdate_ = clock; }
87	  int64_t getLastUpdate() const { return lastUpdate_; }
88	  bool operator<(const WrDiskCacheEntry& rhs) const
89	  {
90	    return sizeKey_ > rhs.sizeKey_ ||
91	           (sizeKey_ == rhs.sizeKey_ && lastUpdate_ < rhs.lastUpdate_);
92	  }
93	
94	  enum { CACHE_ERR_SUCCESS, CACHE_ERR_ERROR };
95	
96	  int getError() const { return error_; }
97	  error_code::Value getErrorCode() const { return errorCode_; }
98	
99	  const DataCellSet& getDataSet() const { return set_; }
100	
101	private:
102	  void deleteDataCells();
103	
104	  size_t sizeKey_;
105	  int64_t lastUpdate_;
106	
107	  size_t size_;
108	
109	  DataCellSet set_;
110	
111	  int error_;
112	  error_code::Value errorCode_;
113	
114	  std::shared_ptr<DiskAdaptor> diskAdaptor_;
115	};
116	
117	} // namespace aria2
118	
119	#endif // D_WR_DISK_CACHE_ENTRY_H
