41	#include "fmt.h"
42	
43	namespace aria2 {
44	
45	WrDiskCache::WrDiskCache(size_t limit) : limit_(limit), total_(0), clock_(0) {}
46	
47	WrDiskCache::~WrDiskCache()
48	{
49	  if (total_) {
50	    A2_LOG_WARN(fmt("Write disk cache is not empty size=%lu",
51	                    static_cast<unsigned long>(total_)));
52	  }
53	}
54	
55	bool WrDiskCache::add(WrDiskCacheEntry* ent)
56	{
57	  ent->setSizeKey(ent->getSize());
58	  ent->setLastUpdate(++clock_);
59	  std::pair<EntrySet::iterator, bool> rv = set_.insert(ent);
60	  if (rv.second) {
61	    total_ += ent->getSize();
62	    ensureLimit();
63	    return true;
64	  }
65	  else {
66	    A2_LOG_WARN(fmt("Found duplicate cache entry a.{size=%lu,clock=%" PRId64
67	                    "} b{size=%lu,clock=%" PRId64 "}",
68	                    static_cast<unsigned long>((*rv.first)->getSize()),
69	                    (*rv.first)->getLastUpdate(),
70	                    static_cast<unsigned long>(ent->getSize()),
71	                    ent->getLastUpdate()));
72	    return false;
73	  }
74	}
75	
76	bool WrDiskCache::remove(WrDiskCacheEntry* ent)
77	{
78	  if (set_.erase(ent)) {
79	    A2_LOG_DEBUG(fmt("Removed cache entry size=%lu, clock=%" PRId64,
80	                     static_cast<unsigned long>(ent->getSize()),
81	                     ent->getLastUpdate()));
82	    total_ -= ent->getSize();
83	    return true;
84	  }
85	  else {
86	    return false;
87	  }
88	}
89	
90	bool WrDiskCache::update(WrDiskCacheEntry* ent, ssize_t delta)
91	{
92	  if (!set_.erase(ent)) {
93	    return false;
94	  }
95	  A2_LOG_DEBUG(fmt("Update cache entry size=%lu, delta=%ld, clock=%" PRId64,
96	                   static_cast<unsigned long>(ent->getSize()),
97	                   static_cast<long>(delta), ent->getLastUpdate()));
98	
99	  ent->setSizeKey(ent->getSize());
100	  ent->setLastUpdate(++clock_);
101	  set_.insert(ent);
102	
103	  if (delta < 0) {
104	    assert(total_ >= static_cast<size_t>(-delta));
105	  }
106	  total_ += delta;
107	  ensureLimit();
108	  return true;
109	}
110	
111	void WrDiskCache::ensureLimit()
112	{
113	  while (total_ > limit_) {
114	    auto i = set_.begin();
115	    WrDiskCacheEntry* ent = *i;
116	    A2_LOG_DEBUG(fmt("Force flush cache entry size=%lu, clock=%" PRId64,
117	                     static_cast<unsigned long>(ent->getSizeKey()),
118	                     ent->getLastUpdate()));
119	    total_ -= ent->getSize();
120	    ent->writeToDisk();
121	    set_.erase(i);
122	
123	    ent->setSizeKey(ent->getSize());
124	    ent->setLastUpdate(++clock_);
125	    set_.insert(ent);
126	  }
127	}
128	
129	} // namespace aria2
