44	
45	namespace aria2 {
46	
47	WrDiskCacheEntry::WrDiskCacheEntry(
48	    const std::shared_ptr<DiskAdaptor>& diskAdaptor)
49	    : sizeKey_(0),
50	      lastUpdate_(0),
51	      size_(0),
52	      error_(CACHE_ERR_SUCCESS),
53	      errorCode_(error_code::UNDEFINED),
54	      diskAdaptor_(diskAdaptor)
55	{
56	}
57	
58	WrDiskCacheEntry::~WrDiskCacheEntry()
59	{
60	  if (!set_.empty()) {
61	    A2_LOG_WARN(fmt("WrDiskCacheEntry is not empty size=%lu",
62	                    static_cast<unsigned long>(size_)));
63	  }
64	  deleteDataCells();
65	}
66	
67	void WrDiskCacheEntry::deleteDataCells()
68	{
69	  for (auto& e : set_) {
70	    delete[] e->data;
71	    delete e;
72	  }
73	  set_.clear();
74	  size_ = 0;
75	}
76	
77	void WrDiskCacheEntry::writeToDisk()
78	{
79	  try {
80	    diskAdaptor_->writeCache(this);
81	  }
82	  catch (RecoverableException& e) {
83	    A2_LOG_ERROR_EX("Error when trying to flush write cache", e);
84	    error_ = CACHE_ERR_ERROR;
85	    errorCode_ = e.getErrorCode();
86	  }
87	  deleteDataCells();
88	}
89	
90	void WrDiskCacheEntry::clear() { deleteDataCells(); }
91	
92	bool WrDiskCacheEntry::cacheData(DataCell* dataCell)
93	{
94	  A2_LOG_DEBUG(fmt("WrDiskCacheEntry cache goff=%" PRId64 ", len=%lu",
95	                   dataCell->goff, static_cast<unsigned long>(dataCell->len)));
96	  if (set_.insert(dataCell).second) {
97	    size_ += dataCell->len;
98	    return true;
99	  }
100	  else {
101	    return false;
102	  }
103	}
104	
105	size_t WrDiskCacheEntry::append(int64_t goff, const unsigned char* data,
106	                                size_t len)
107	{
108	  if (set_.empty()) {
109	    return 0;
110	  }
111	  auto i = set_.end();
112	  --i;
113	  if (static_cast<int64_t>((*i)->goff + (*i)->len) == goff) {
114	    size_t wlen = std::min((*i)->capacity - (*i)->len, len);
115	    memcpy((*i)->data + (*i)->offset + (*i)->len, data, wlen);
116	    (*i)->len += wlen;
117	    size_ += wlen;
118	    return wlen;
119	  }
120	  else {
121	    return 0;
122	  }
123	}
124	
125	} // namespace aria2
