299	
300	void Piece::initWrCache(WrDiskCache* diskCache,
301	                        const std::shared_ptr<DiskAdaptor>& diskAdaptor)
302	{
303	  if (!diskCache) {
304	    return;
305	  }
306	  assert(!wrCache_);
307	  wrCache_ = make_unique<WrDiskCacheEntry>(diskAdaptor);
308	  bool rv = diskCache->add(wrCache_.get());
309	  assert(rv);
310	}
311	
312	void Piece::flushWrCache(WrDiskCache* diskCache)
313	{
314	  if (!diskCache) {
315	    return;
316	  }
317	  assert(wrCache_);
318	  ssize_t size = static_cast<ssize_t>(wrCache_->getSize());
319	  diskCache->update(wrCache_.get(), -size);
320	  wrCache_->writeToDisk();
321	}
322	
323	void Piece::clearWrCache(WrDiskCache* diskCache)
324	{
325	  if (!diskCache) {
326	    return;
327	  }
328	  assert(wrCache_);
329	  ssize_t size = static_cast<ssize_t>(wrCache_->getSize());
330	  diskCache->update(wrCache_.get(), -size);
331	  wrCache_->clear();
332	}
333	
334	void Piece::updateWrCache(WrDiskCache* diskCache, unsigned char* data,
335	                          size_t offset, size_t len, size_t capacity,
336	                          int64_t goff)
337	{
338	  if (!diskCache) {
339	    return;
340	  }
341	  assert(wrCache_);
342	  A2_LOG_DEBUG(fmt("updateWrCache entry=%p", wrCache_.get()));
343	  auto cell = new WrDiskCacheEntry::DataCell();
344	  cell->goff = goff;
345	  cell->data = data;
346	  cell->offset = offset;
347	  cell->len = len;
348	  cell->capacity = capacity;
349	  bool rv;
350	  rv = wrCache_->cacheData(cell);
351	  assert(rv);
352	  rv = diskCache->update(wrCache_.get(), len);
353	  assert(rv);
354	}
355	
356	size_t Piece::appendWrCache(WrDiskCache* diskCache, int64_t goff,
357	                            const unsigned char* data, size_t len)
358	{
359	  if (!diskCache) {
360	    return 0;
361	  }
362	  assert(wrCache_);
363	  size_t delta = wrCache_->append(goff, data, len);
364	  bool rv;
365	  if (delta > 0) {
366	    rv = diskCache->update(wrCache_.get(), delta);
367	    assert(rv);
368	  }
369	  return delta;
370	}
371	
372	void Piece::releaseWrCache(WrDiskCache* diskCache)
373	{
374	  if (diskCache && wrCache_) {
375	    diskCache->remove(wrCache_.get());
376	    wrCache_.reset();
377	  }
378	}
