53	
54	ssize_t SinkStreamFilter::transform(const std::shared_ptr<BinaryStream>& out,
55	                                    const std::shared_ptr<Segment>& segment,
56	                                    const unsigned char* inbuf, size_t inlen)
57	{
58	  size_t wlen;
59	  if (inlen > 0) {
60	    if (segment->getLength() > 0) {
61	      // We must not write data larger than available space in
62	      // segment.
63	      assert(segment->getLength() >= segment->getWrittenLength());
64	      size_t lenAvail = segment->getLength() - segment->getWrittenLength();
65	      wlen = std::min(inlen, lenAvail);
66	    }
67	    else {
68	      wlen = inlen;
69	    }
70	    const std::shared_ptr<Piece>& piece = segment->getPiece();
71	    if (piece->getWrDiskCacheEntry()) {
72	      assert(wrDiskCache_);
73	      // If we receive small data (e.g., 1 or 2 bytes), cache entry
74	      // becomes a headache. To mitigate this problem, we allocate
75	      // cache buffer at least 4KiB and append the data to the
76	      // contagious cache data.
77	      size_t alen = piece->appendWrCache(
78	          wrDiskCache_, segment->getPositionToWrite(), inbuf, wlen);
79	      if (alen < wlen) {
80	        size_t len = wlen - alen;
81	        size_t capacity = std::max(len, static_cast<size_t>(4_k));
82	        auto dataCopy = new unsigned char[capacity];
83	        memcpy(dataCopy, inbuf + alen, len);
84	        piece->updateWrCache(wrDiskCache_, dataCopy, 0, len, capacity,
85	                             segment->getPositionToWrite() + alen);
86	      }
87	    }
88	    else {
89	      out->writeData(inbuf, wlen, segment->getPositionToWrite());
90	    }
91	    if (hashUpdate_) {
92	      segment->updateHash(segment->getWrittenLength(), inbuf, wlen);
93	    }
94	    segment->updateWrittenLength(wlen);
95	  }
96	  else {
97	    wlen = 0;
98	  }
99	  bytesProcessed_ = wlen;
100	  return bytesProcessed_;
101	}
