48	  CPPUNIT_ASSERT_EQUAL((size_t)20, dc.getSize());
49	
50	  WrDiskCacheEntry e3(adaptor_);
51	  e3.cacheData(createDataCell(10, "hello"));
52	  CPPUNIT_ASSERT(dc.add(&e3));
53	  CPPUNIT_ASSERT_EQUAL((size_t)15, dc.getSize());
