56	  CPPUNIT_ASSERT_EQUAL((size_t)0, e1.getSize());
57	
58	  e3.cacheData(createDataCell(15, " world"));
59	  CPPUNIT_ASSERT(dc.update(&e3, 6));
60	
61	  // e3 is flushed to the disk
62	  CPPUNIT_ASSERT_EQUAL(std::string("who knows?hello world"),
63	                       writer_->getString());
64	  CPPUNIT_ASSERT_EQUAL((size_t)0, e3.getSize());
65	  CPPUNIT_ASSERT_EQUAL((size_t)10, dc.getSize());
66	
67	  e2.cacheData(createDataCell(31, "01234567890"));
68	  CPPUNIT_ASSERT(dc.update(&e2, 11));
